#!/usr/bin/env bash
# Hardware-forwarded opposite-node paths for RoCEnante (generated by spark/ring/mesh/plan.py). Idempotent.
set -euo pipefail
tc qdisc show dev enp1s0f0np0 | grep clsact >/dev/null || tc qdisc add dev enp1s0f0np0 clsact
tc qdisc show dev enp1s0f1np1 | grep clsact >/dev/null || tc qdisc add dev enp1s0f1np1 clsact
tc filter show dev enp1s0f0np0 ingress pref 49152 | grep flower >/dev/null || tc filter add dev enp1s0f0np0 ingress protocol 0x88b5 pref 49152 handle 49152 flower skip_sw src_mac 4c:bb:47:80:f1:42 dst_mac 4c:bb:47:80:f3:28 action pedit ex munge eth type set 0x0800 pipe action pedit ex munge eth dst set 4c:bb:47:80:b2:0d pipe action mirred egress redirect dev enp1s0f1np1
tc -s filter show dev enp1s0f0np0 ingress pref 49152 | grep in_hw >/dev/null || { echo 'rule pref 49152 on enp1s0f0np0 is not in hardware'; exit 3; }
tc filter show dev enp1s0f1np1 ingress pref 49162 | grep flower >/dev/null || tc filter add dev enp1s0f1np1 ingress protocol 0x88b5 pref 49162 handle 49162 flower skip_sw src_mac 4c:bb:47:80:b2:0d dst_mac 4c:bb:47:80:f3:29 action pedit ex munge eth type set 0x0800 pipe action pedit ex munge eth dst set 4c:bb:47:80:f1:42 pipe action mirred egress redirect dev enp1s0f0np0
tc -s filter show dev enp1s0f1np1 ingress pref 49162 | grep in_hw >/dev/null || { echo 'rule pref 49162 on enp1s0f1np1 is not in hardware'; exit 3; }
ip route show exact 10.251.20.10/32 | grep . >/dev/null || ip route add 10.251.20.10/32 via 10.251.20.6 dev enp1s0f1np1 src 10.251.20.5
ip route show exact 10.100.241.13/32 | grep . >/dev/null || ip route add 10.100.241.13/32 via 10.100.241.1 dev enP2p1s0f0np0 src 10.100.241.2
for d in roceP2p1s0f0 rocep1s0f1; do systemctl start spark-ring-mesh-marker@$d; done
sleep 2; for d in roceP2p1s0f0 rocep1s0f1; do systemctl is-active --quiet spark-ring-mesh-marker@$d || { echo marker $d not active; exit 4; }; done
echo mesh-up OK
